import{_ as a,o as t,c as r,a0 as o}from"./chunks/framework.BQGW-Zpy.js";const n="/Cross-Border-Payments/assets/home.DiJvCxyS.png",s="/Cross-Border-Payments/assets/how-it-works.499mgR4L.png",i="/Cross-Border-Payments/assets/send-money.DR_Q44mI.png",c="/Cross-Border-Payments/assets/tamper-demo.D0VmfSe3.png",h="/Cross-Border-Payments/assets/community.DPlbCWqQ.png",d="/Cross-Border-Payments/assets/landing.cwp4Xy4o.png",w=JSON.parse('{"title":"Site Tour","description":"","frontmatter":{},"headers":[],"relativePath":"reference/site-tour.md","filePath":"reference/site-tour.md"}'),l={name:"reference/site-tour.md"};function p(m,e,u,f,g,y){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="site-tour" tabindex="-1">Site Tour <a class="header-anchor" href="#site-tour" aria-label="Permalink to &quot;Site Tour&quot;">​</a></h1><p>Every page on the live site, with a screenshot and what it does.</p><h2 id="home" tabindex="-1">Home <a class="header-anchor" href="#home" aria-label="Permalink to &quot;Home&quot;">​</a></h2><p><img src="'+n+'" alt="Home page"></p><p>The landing page. States the core promise directly: fiat-to-fiat conversion carried across borders on the stablecoin rail, with no wallet ever touching either side of the transfer. The globe on the right shows a live routing-anchor status card. Below the fold: hero statistics (countries, currencies, settlement speed, verifiability), the four core benefits (no wallet required, lightning-fast settlement, countries supported, compliance built in), a &quot;how a transfer actually moves&quot; walkthrough, the compliance and security section, supported currencies, potential settlement partners, and the settlement-networks breakdown showing Hedera as the always-on anchor network alongside where liquidity actually sits (Ethereum, Solana, BNB Chain, Base). Sections fade in with a soft blur as the page is scrolled.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p><img src="'+s+'" alt="How It Works page"></p><p>A full walkthrough of one corridor, start to finish, Portugal to Armenia, with every anchor point to Hedera marked along the way: the interactive use-case video embedded at the top, and a horizontal, scrollable backend-call map below it showing the exact sequence of API/Hedera calls involved, with the HCS anchor steps visually distinguished from the rest.</p><h2 id="send-money" tabindex="-1">Send Money <a class="header-anchor" href="#send-money" aria-label="Permalink to &quot;Send Money&quot;">​</a></h2><p><img src="'+i+'" alt="Send Money page"></p><p>The actual transfer flow: amount and currency, recipient details, payout method, review, and payment, a three-step form with no wallet address, private key, or seed phrase requested at any point. Submitting creates a real transfer through the backend, which anchors a compliance record to Hedera Consensus Service and settles through the corridor router.</p><h2 id="tamper-demo" tabindex="-1">Tamper Demo <a class="header-anchor" href="#tamper-demo" aria-label="Permalink to &quot;Tamper Demo&quot;">​</a></h2><p><img src="'+c+'" alt="Tamper Demo page"></p><p>A live demonstration of why the Hedera anchor matters. Shows an original compliance record, its hash, and a button to modify the off-chain record. Modifying it and re-verifying flips the result from a match to a mismatch, in front of the person using it, not just described in text. Also links directly to the real anchored records on HashScan.</p><h2 id="community" tabindex="-1">Community <a class="header-anchor" href="#community" aria-label="Permalink to &quot;Community&quot;">​</a></h2><p><img src="'+h+'" alt="Community page"></p><p>Where senders share real experiences. Posting requires a Community Usage Code, a code issued once, automatically, only after a transaction has a real Hedera anchor, not the Hedera hash itself (which is public and would let anyone post). The form rejects a missing or unrecognized code, and rejects a message under 5 characters.</p><h2 id="landing" tabindex="-1">Landing <a class="header-anchor" href="#landing" aria-label="Permalink to &quot;Landing&quot;">​</a></h2><p><img src="'+d+'" alt="Landing page"></p><p>A pitch-style page: the problem (correspondent banking is shrinking, not scaling), the solution (breaking the route apart and riding the stablecoin rail), who feels this problem directly, and the first target markets by corridor.</p><h2 id="track-transaction" tabindex="-1">Track Transaction <a class="header-anchor" href="#track-transaction" aria-label="Permalink to &quot;Track Transaction&quot;">​</a></h2><p>Look up any transaction by ID and see its status, Hedera reference, and a path to independent verification. Falls back to the seeded demo transaction (<code>TXN-9KF3XQ2</code>) when nothing else is found, so the page always has something real to show rather than a dead end.</p><h2 id="compliance-verification" tabindex="-1">Compliance Verification <a class="header-anchor" href="#compliance-verification" aria-label="Permalink to &quot;Compliance Verification&quot;">​</a></h2><p>The verification page for a specific transaction: the compliance record&#39;s fields, the Hedera Consensus Service reference (topic, transaction, consensus timestamp), and a button that checks the record&#39;s hash against what&#39;s actually anchored on the public Mirror Node, not a local simulation.</p><h2 id="transaction-receipt" tabindex="-1">Transaction Receipt <a class="header-anchor" href="#transaction-receipt" aria-label="Permalink to &quot;Transaction Receipt&quot;">​</a></h2><p>A printable/exportable receipt for a completed transfer: sender and recipient details, amounts and fees, status, and the Hedera network record. Includes the Community Usage Code card when the transaction has a real anchor.</p>',26)])])}const k=a(l,[["render",p]]);export{w as __pageData,k as default};
